#include <stdio.h>
#include <string.h>

#define MAXN 256

static int find(char arr[][32], int n, const char *pid) {
    for (int i = 0; i < n; ++i)
        if (!strcmp(arr[i], pid)) return i;
    return -1;
}

static void remove_at(char arr[][32], int *n, int idx) {
    for (int i = idx; i + 1 < *n; ++i) strcpy(arr[i], arr[i + 1]);
    (*n)--;
}

/* ops: 形如 "create p1" 的字符串数组；n 为操作条数
 * out: 输出就绪队列 pid；返回就绪队列长度 */
int solve(char ops[][32], int n, char out[][32]) {
    char ready[MAXN][32];   int rn = 0;
    char blocked[MAXN][32]; int bn = 0;

    for (int i = 0; i < n; ++i) {
        char cmd[32], pid[32];
        pid[0] = '\0';
        sscanf(ops[i], "%31s %31s", cmd, pid);

        if (!strcmp(cmd, "create")) {
            strcpy(ready[rn++], pid);
        } else if (!strcmp(cmd, "block")) {
            int k = find(ready, rn, pid);
            if (k >= 0) remove_at(ready, &rn, k);
            strcpy(blocked[bn++], pid);
        } else if (!strcmp(cmd, "wakeup")) {
            int k = find(blocked, bn, pid);
            if (k >= 0) {
                remove_at(blocked, &bn, k);
                strcpy(ready[rn++], pid);
            }
        } else if (!strcmp(cmd, "exit")) {
            int k = find(ready, rn, pid);
            if (k >= 0) remove_at(ready, &rn, k);
            k = find(blocked, bn, pid);
            if (k >= 0) remove_at(blocked, &bn, k);
        }
    }

    for (int i = 0; i < rn; ++i) strcpy(out[i], ready[i]);
    return rn;
}
